// DS | catalog.цеха | id ( $h.цех) | Select () | Value ( юрлицо )

var workshop = $h.цех;
var tableProjects = await from('catalog.цеха')
    .select (['юрлицо'])
    .where ('id = @workshop')
    .parameter ('workshop', workshop, 11)
    .query();

return tableProjects.rows[0].юрлицо;

